import React, { useEffect, useState } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import api from '../api/axios';
import SeatMap from '../components/SeatMap';
import styles from './SeatSelection.module.css';

export default function SeatSelection() {
  const { id } = useParams();
  const navigate = useNavigate();
  const [showtime, setShowtime] = useState(null);
  const [selectedSeats, setSelectedSeats] = useState([]);

  useEffect(() => {
    api.get(`/showtimes/${id}`).then(({ data }) => setShowtime(data)).catch(console.error);
  }, [id]);

  const handleSeatClick = (seat) => {
    setSelectedSeats((prev) => {
      const exists = prev.find((s) => s.seatNumber === seat.seatNumber);
      if (exists) return prev.filter((s) => s.seatNumber !== seat.seatNumber);
      if (prev.length >= 8) return prev; // max 8 seats
      return [...prev, seat];
    });
  };

  const totalAmount = selectedSeats.reduce((sum, s) => sum + s.price, 0);

  const handleProceed = () => {
    if (selectedSeats.length === 0) return;
    navigate('/checkout', { state: { showtime, selectedSeats, totalAmount } });
  };

  if (!showtime) return <p className={styles.loading}>Loading seats...</p>;

  return (
    <div className={styles.container}>
      <h2>{showtime.movie?.title}</h2>
      <p className={styles.meta}>{showtime.theater} • {showtime.screen} • {showtime.date} • {showtime.startTime}</p>

      <SeatMap seats={showtime.seats} selectedSeats={selectedSeats} onSeatClick={handleSeatClick} />

      <div className={styles.summary}>
        <div>
          <p>{selectedSeats.length} seat(s) selected: {selectedSeats.map((s) => s.seatNumber).join(', ')}</p>
          <p className={styles.total}>Total: ₹{totalAmount}</p>
        </div>
        <button className={styles.btn} onClick={handleProceed} disabled={selectedSeats.length === 0}>
          Proceed to Payment
        </button>
      </div>
    </div>
  );
}
